import csv
import re
import io

data = """"Ycuá Bolaños Süpermarketi Harabeleri","Asunción","Paraguay","2004 yılında çıkan devasa bir yangında, patronların 'müşteriler hırsızlık yapmasın' diye kapıları kilitlemesi sonucu 400'e yakın insanın diri diri yandığı o korkunç beton enkazı. Kararmış duvarların etrafında gezerken, kilitli camlara vuran o mutlak alev paniği ve arafta kalan yanmış ruhların feryatları auranızı paramparça eder.",5"Cerro Corá Milli Parkı (Kanlı Savaş Meydanı)","Amambay","Paraguay","Paraguay nüfusunun neredeyse yarısının yok olduğu Üçlü İttifak Savaşı'nın (1870) o son ve en acımasız katliamının yaşandığı, ormanın içindeki bu izole vadi. Geceleri ormandan yankılanan at kişnemeleri ve kılıçtan geçirilen çocuk askerlerin toprağa sinmiş o saf, tarifsiz kederi nefesinizi keser.",5"Palacio de López (Diktatörlük Zindanları)","Asunción","Paraguay","Alfredo Stroessner'in 35 yıllık kanlı diktatörlüğü boyunca sayısız muhalifin sorgulandığı, işkence gördüğü ve nehre atıldığı o görkemli başkanlık sarayının karanlık alt katları. Oksijensiz dehlizlerden sızan o sülfürik devlet terörü ve 'kaybedilenlerin' duvarlara kazınmış çığlıkları zihninizi daraltır.",5"Hotel del Lago (Terk Edilmiş San Bernardino)","San Bernardino","Paraguay","Ypacaraí Gölü kıyısında kurulan, 20. yüzyılın başlarında kaçak Nazilerin ve Alman okültistlerin saklandığı bu ürkütücü ve tarihi otel. Gizli ayinlerin yapıldığı ahşap odalarda esen soğuk rüzgar ve intihar ettiği söylenen gölgelerin yaydığı o ağır, Nasyonal Sosyalist paranoya ruhunuzu ezer.",4"Eski La Encarnación Kilisesi","Asunción","Paraguay","Savaşlar ve devrimler boyunca defalarca yıkılıp yeniden yapılan, gizli yeraltı tünelleri ve antik mahzenleriyle bilinen devasa katedral. Ay ışığının aydınlattığı boş neflerde gezinirken, geçmişte bu tünellerde saklanarak can veren sivillerin o yoğun, Katolik keder frekansı sizi transa sokar.",4"Castillo San Felipe del Morro (El Morro)","San Juan","Porto Riko","Karayipler'in en uç noktasında denize meydan okuyan, 400 yıl boyunca korsanların ve yabancı donanmaların kanlı kuşatmalarına göğüs germiş o devasa İspanyol kalesi. Karanlık cephaneliklerinde ve hücrelerinde yankılanan top sesleri ile okyanusa düşüp boğulan İspanyol askerlerinin o ağır askeri arafı empatları felç eder.",5"Castillo de San Cristóbal (Şeytanın Nöbet Kulübesi)","San Juan","Porto Riko","Kalenin okyanusa uzanan en ıssız ve fırtınalı ucunda yer alan, efsaneye göre nöbet tutan askerlerin geceleri çığlık bile atamadan gizemli bir şekilde yok olduğu o meşhur 'Garita del Diablo'. Dalgaların dövdüğü bu izole taştan hücrenin içine girdiğinizde o anlık, yutucu boyutsal boşluk hissi aklınızı başınızdan alır.",5"Terk Edilmiş Guajataca Tüneli","Isabela","Porto Riko","20. yüzyılın başlarında adanın şeker kamışı trenleri için kayalara oyulmuş, 1910'larda korkunç bir tren kazasında onlarca işçinin can verdiği zifiri karanlık geçit. Tünelin sonundaki ışığa doğru yürürken, arkanızdan gelen hayalet trenin o ağır, sarsıcı mekanik uğultusu ve kurbanların fısıltıları klostrofobiyi tetikler.",4"Hotel El Convento (Eski Karmelit Manastırı)","San Juan","Porto Riko","1600'lerden kalma eski bir Katolik manastırı olan ancak sonradan otele dönüştürülen bu kolonyal yapı. Uzun, sarı koridorlarında gece yarısı duyulan rahibe cübbelerinin o hafif hışırtısı ve manastırın kurucusu Doña Ana'nın odalara sinmiş o otoriter, yoğun dini nezaret enerjisi kanınızı dondurur.",4"Teatro Tapia (Lanetli Tiyatro)","San Juan","Porto Riko","Amerika kıtasının en eski ve aktif tiyatrolarından biri olan, ancak sahnede ölen bir aktrisin ve locada asılı kalan eski bir koronun ruhu tarafından ele geçirildiği söylenen o görkemli bina. Sahnenin arkasındaki kapkaranlık kulislerde hissedilen o ağır, tiyatral ölüm enerjisi ve balkondan sizi izleyen görünmez gözler nefesinizi keser.",4"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Paraguay ve Porto Riko kayitlari eklendi.")
